CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS players(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), display_name text NOT NULL, district_id text NOT NULL, position jsonb NOT NULL DEFAULT '{"x":0,"y":0,"z":0}', xp bigint NOT NULL DEFAULT 0, reputation bigint NOT NULL DEFAULT 0, needs jsonb NOT NULL, avatar jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ledger(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), player_id uuid NOT NULL REFERENCES players(id), amount bigint NOT NULL CHECK(amount<>0), reason text NOT NULL, reference text, idempotency_key text UNIQUE, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS ledger_player_created_idx ON ledger(player_id,created_at DESC);
CREATE TABLE IF NOT EXISTS inventory(player_id uuid NOT NULL REFERENCES players(id), item_id text NOT NULL, quantity int NOT NULL CHECK(quantity>=0), PRIMARY KEY(player_id,item_id));
CREATE TABLE IF NOT EXISTS messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sender_id uuid NOT NULL REFERENCES players(id), recipient_id uuid NOT NULL REFERENCES players(id), body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS messages_participants_idx ON messages(sender_id,recipient_id,created_at DESC);
CREATE TABLE IF NOT EXISTS relationships(player_id uuid NOT NULL REFERENCES players(id), other_id uuid NOT NULL REFERENCES players(id), status text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(player_id,other_id));
CREATE TABLE IF NOT EXISTS owned_vehicles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), player_id uuid NOT NULL REFERENCES players(id), model_id text NOT NULL, fuel numeric NOT NULL, condition numeric NOT NULL, odometer_km numeric NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS homes(player_id uuid PRIMARY KEY REFERENCES players(id), property_id text NOT NULL, district_id text NOT NULL, mode text NOT NULL, acquired_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS businesses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES players(id), type_id text NOT NULL, name text NOT NULL, district_id text NOT NULL, level int NOT NULL DEFAULT 1, reputation int NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS payment_receipts(provider text NOT NULL, transaction_id text NOT NULL, player_id uuid NOT NULL REFERENCES players(id), game_amount bigint NOT NULL, verified_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(provider,transaction_id));
CREATE TABLE IF NOT EXISTS moderation_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reporter_id uuid REFERENCES players(id), target_type text NOT NULL, target_id text NOT NULL, reason text NOT NULL, state text NOT NULL DEFAULT 'open', created_at timestamptz NOT NULL DEFAULT now());
